// src/parser/mod.rs

// Pulls in the parser generated by build.rs into OUT_DIR/parser/grammar.rs
lalrpop_util::lalrpop_mod!(grammar, "/parser/grammar.rs");

pub use grammar::ProgramParser;

use crate::ast::Integer;
use crate::lexer::lexer_impl::Lexer;
use crate::lexer::tokens::{LexingError, Token};
use std::fs;

pub fn parse_file(
    file: String,
) -> Result<Vec<Integer>, lalrpop_util::ParseError<usize, Token, LexingError>> {
    let source = fs::read_to_string(&file).expect("could not open file");

    let parser = grammar::ProgramParser::new();
    parser.parse(Lexer::new(&source))
}